<?php
require_once __DIR__.'/auth.php';$msg='';$err='';
function upload_portfolio(?string $old=null):string{if(empty($_FILES['image']['name']))return $old??'';$f=$_FILES['image'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>8*1024*1024)throw new RuntimeException('Gambar maksimal 8 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$map=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($map[$mime]))throw new RuntimeException('Gambar harus JPG, PNG, atau WEBP.');$name='portfolio_'.bin2hex(random_bytes(7)).'.'.$map[$mime];$dir=__DIR__.'/../assets/portfolio/';if(!is_dir($dir))mkdir($dir,0755,true);if(!move_uploaded_file($f['tmp_name'],$dir.$name))throw new RuntimeException('Upload gagal.');if($old&&str_starts_with($old,'assets/portfolio/')&&is_file(__DIR__.'/../'.$old))@unlink(__DIR__.'/../'.$old);return 'assets/portfolio/'.$name;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??'');$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');if(!$title)throw new RuntimeException('Judul wajib diisi.');$old='';if($id){$q=$pdo->prepare('SELECT image FROM portfolios WHERE id=?');$q->execute([$id]);$old=$q->fetchColumn()?:'';}$image=upload_portfolio($old);if(!$image)throw new RuntimeException('Pilih gambar portfolio.');if($id)$pdo->prepare('UPDATE portfolios SET title=?,description=?,image=? WHERE id=?')->execute([$title,$desc,$image,$id]);else $pdo->prepare('INSERT INTO portfolios(title,description,image) VALUES(?,?,?)')->execute([$title,$desc,$image]);$msg='Portfolio tersimpan.';}elseif($action==='delete'){$q=$pdo->prepare('SELECT image FROM portfolios WHERE id=?');$q->execute([$id]);$p=$q->fetchColumn();$pdo->prepare('DELETE FROM portfolios WHERE id=?')->execute([$id]);if($p&&str_starts_with($p,'assets/portfolio/')&&is_file(__DIR__.'/../'.$p))@unlink(__DIR__.'/../'.$p);$msg='Portfolio dihapus.';}}catch(Throwable $x){$err=$x->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM portfolios WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query('SELECT * FROM portfolios ORDER BY id DESC')->fetchAll();admin_header('Kelola Portfolio','portfolio');if($msg)echo '<div class="notice success-notice">'.e($msg).'</div>';if($err)echo '<div class="notice error-notice">'.e($err).'</div>';
?><section class="panel"><h2><?=$edit?'Edit Portfolio':'Tambah Portfolio'?></h2><form method="post" enctype="multipart/form-data" class="member-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'0')?>"><label>Judul<input name="title" value="<?=e($edit['title']??'')?>" required></label><label>Gambar<input type="file" name="image" accept="image/jpeg,image/png,image/webp" <?=$edit?'':'required'?>><small>JPG/PNG/WEBP, maksimal 8 MB.</small></label><label class="full">Deskripsi<textarea name="description"><?=e($edit['description']??'')?></textarea></label><div class="full"><button class="save">Simpan Portfolio</button><?php if($edit):?> <a class="cancel" href="portfolio.php">Batal</a><?php endif;?></div></form></section><section class="panel" style="margin-top:22px"><h2>Portfolio Website</h2><div class="portfolio-admin-grid"><?php foreach($rows as $r):?><article class="portfolio-admin-card"><img src="../<?=e($r['image'])?>" alt="<?=e($r['title'])?>"><h3><?=e($r['title'])?></h3><p><?=e($r['description'])?></p><div class="member-card-actions"><a class="save" href="portfolio.php?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Hapus portfolio ini?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="del">Hapus</button></form></div></article><?php endforeach;?></div></section><?php admin_footer(); ?>
